#!/usr/bin/env bash
# Some portions generated by Codex. Fixed four workloads, four paired blocks each.
set -euo pipefail
cd "$(dirname "$0")/../../.."
for shape in small6 reference6 wide30 large6; do
 i=0
 for arm in base stack stack base base stack stack base; do
  i=$((i+1))
  python3 experiments/threadlocal-audit/range-workbench/run.py "$arm" "matched-$shape-$(printf '%02d' "$i")-$arm" --workload "$shape" --warmups 60 --iterations 20
 done
done
